\"_17\":182,\"_73\":-5,\"_140\":722},\"71f25b05-2ea1-4495-8f50-af4169fd650d\",[724],{\"_68\":725},[726],{\"_17\":190,\"_73\":-5,\"_140\":727},\"028605b2-0ff3-45ba-b095-9006e73215fd\",[729],{\"_68\":730},[731],{\"_17\":198,\"_73\":-5,\"_140\":732},\"fcd9abcd-9389-4b31-97fd-af6b0fb8ce82\",{\"_55\":734},{\"_735\":736},\"social\",[737,738,739,740,741,742,743,744,745,746,747,748,749,750,751,752,753,754,755,756,757,758,759,760],{\"_761\":762,\"_73\":833,\"_9\":834,\"_765\":835},{\"_761\":762,\"_73\":830,\"_9\":831,\"_765\":832},{\"_761\":762,\"_73\":827,\"_9\":828,\"_765\":829},{\"_761\":762,\"_73\":824,\"_9\":825,\"_765\":826},{\"_761\":762,\"_73\":821,\"_9\":822,\"_765\":823},{\"_761\":762,\"_73\":818,\"_9\":819,\"_765\":820},{\"_761\":762,\"_73\":815,\"_9\":816,\"_765\":817},{\"_761\":762,\"_73\":812,\"_9\":813,\"_765\":814},{\"_761\":762,\"_73\":809,\"_9\":810,\"_765\":811},{\"_761\":762,\"_73\":806,\"_9\":807,\"_765\":808},{\"_761\":762,\"_73\":803,\"_9\":804,\"_765\":805},{\"_761\":762,\"_73\":800,\"_9\":801,\"_765\":802},{\"_761\":762,\"_73\":797,\"_9\":798,\"_765\":799},{\"_761\":762,\"_73\":794,\"_9\":795,\"_765\":796},{\"_761\":762,\"_73\":791,\"_9\":792,\"_765\":793},{\"_761\":762,\"_73\":788,\"_9\":789,\"_765\":790},{\"_761\":762,\"_73\":785,\"_9\":786,\"_765\":787},{\"_761\":762,\"_73\":782,\"_9\":783,\"_765\":784},{\"_761\":762,\"_73\":779,\"_9\":780,\"_765\":781},{\"_761\":762,\"_73\":776,\"_9\":777,\"_765\":778},{\"_761\":762,\"_73\":773,\"_9\":774,\"_765\":775},{\"_761\":762,\"_73\":770,\"_9\":771,\"_765\":772},{\"_761\":762,\"_73\":767,\"_9\":768,\"_765\":769},{\"_761\":762,\"_73\":763,\"_9\":764,\"_765\":766},\"media\",\"linkedin\",\"58a01e9a-13f2-4430-983e-f791318553d8\",\"https://www.linkedin.com/posts/ihc-uae_davos-ihc-ihchouse-activity-7419866021920124928-HHIv?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"info\",\"\u003cp\u003eDay 3 at IHC House @ Davos brought together leaders from across sectors for a full day of dialogue, collaboration, and engagement, with Manus Cranny of The National News taking us through the day.\u003c/p\u003e\\n\u003cp\u003eThe IHC delegation hosted a series of sessions with esteemed guests, including a breakfast hosted by Ajay Bhatia, ADI Foundation Council Member and CEO of Sirius International Holding, Mastercard CEO Michael Miebach, and Circle CEO Jeremy Allaire focused on innovating for growth; an AI for Good roundtable with Global Citizen CEO Hugh Evans; a Whiteshield event on labour resilience with IHC Chief Strategy \u0026amp; Growth Officer Peter Abraam; and a panel exploring AI as the next frontier of global growth led by Aleria CEO Eric Leandri.\u003c/p\u003e\",\"28a279ca-023b-4b2c-93db-9ae3707ee268\",\"https://www.linkedin.com/posts/ihc-uae_ihc-ihchouse-wef26-activity-7420058196398194688-vc9r?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eAt IHC House in Davos, H.H. Sheikh Zayed bin Hamdan bin Zayed Al Nahyan, Chairman of 2PointZero Group, met with Robin Vince, CEO of BNY, and Hani Kablawi, Head of International at BNY on the sidelines of the World Economic Forum Annual Meeting 2026.\u0026nbsp;\u003c/p\u003e\\n\u003cp\u003eThe meeting brought together Syed Basar Shueb, CEO of IHC, Sofia Lasky, Board Member of IHC, and Hamad Salem Al Ameri, Group CEO of Alpha Dhabi Holding, for discussions on key trends shaping global markets and the importance of forward-looking, sustainable approaches to investment, underscoring the value of cross-sector collaboration in an increasingly interconnected global economy.\u003c/p\u003e\",\"4804455a-a372-496e-a769-a695370ecc29\",\"https://www.linkedin.com/posts/ihc-uae_ihc-ihchouse-wef26-activity-7420162919713316864-_cC3?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eHis Highness Sheikh Zayed bin Hamdan bin Zayed Al Nahyan, Chairman of 2PointZero Group, and Syed Basar Shueb, CEO of IHC, met with Oliver B\u0026auml;te, CEO of Allianz, one of the world\u0026rsquo;s leading insurers and asset managers, at IHC House in Davos, on the sidelines of the World Economic Forum Annual Meeting. The meeting was attended by Sofia Lasky, Board Member of IHC; Hamad Salem Al Ameri, Group CEO of Alpha Dhabi Holding; Fawad Zahid, Group Financial Controller at IHC; and Ajay Bhatia, CEO of Sirius International Holding.\u003c/p\u003e\\n\u003cp\u003eThe discussion explored long-term value creation, institutional resilience, and sustainable growth, highlighting the importance of responsible stewardship and enduring partnerships across global markets.\u003c/p\u003e\",\"971e7440-a808-4b24-986c-985f5998ef17\",\"https://www.linkedin.com/posts/ihc-uae_ihc-ihchouse-wef26-activity-7420259430543331328--_zp?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eDay 4 at IHC House @ Davos continued the momentum with powerful conversations on growth, performance, and global partnership, bringing together leaders from finance, sport, and investment, as recapped by Manus Cranny of The National News.\u003c/p\u003e\\n\u003cp\u003eThe day featured a series of high-level engagements, including a fireside chat on accelerating global growth with Robin Vince, CEO of BNY, and Paul Keary, CEO of Teneo; alongside a thought-provoking discussion with Alex Rodriguez, former MLB World Series champion and CEO of A-Rod Corp, and Chris Wearing, Chairman of Teneo International, exploring what high-performance sport reveals about capital allocation and long-term value creation.\u003c/p\u003e\",\"ede03d1f-2cf2-4646-99c3-c2b8e2f4561f\",\"https://www.linkedin.com/posts/ihc-uae_ihc-gc-partnership-activity-7420455810725474305-f58j?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC and Global Citizen, the world\u0026rsquo;s largest movement to end extreme poverty, announced a new multi-year strategic partnership at the IHC House during the World Economic Forum Annual Meeting in Davos.\u0026nbsp;\u003c/p\u003e\\n\u003cp\u003eUnder the partnership, IHC will support Global Citizen\u0026rsquo;s advocacy efforts and global programming, including existing initiatives and the development of new engagements, particularly in the UAE and Middle East. The collaboration reflects Global Citizen\u0026rsquo;s and IHC\u0026rsquo;s shared commitment to supporting platforms that mobilize governments, businesses, and citizens to eradicate extreme poverty.\u0026nbsp;\u003c/p\u003e\",\"3190ed38-2cea-4171-ad40-f1d22607a6f8\",\"https://www.linkedin.com/posts/ihc-uae_davos-ihc-ifza-activity-7420784055811620864-GZDu?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC and International Free Zone Authority | IFZA have unveiled a landmark global partnership at the World Economic Forum Annual Meeting 2026 in Davos.\u003c/p\u003e\\n\u003cp\u003eThe collaboration brings together IFZA\u0026rsquo;s globally connected business ecosystems with IHC\u0026rsquo;s investment scale, governance, and platform-building expertise to co-develop next-generation free zones and special economic platforms across international markets.\u003c/p\u003e\",\"8781167f-cf5e-48cd-9cc6-019910428cac\",\"https://www.linkedin.com/posts/ihc-uae_ihc-lunate-activity-7422682585920614401-EMJP?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eLunate has announced that H.E. Mohamed Hassan Alsuwaidi has been appointed Executive Chairman and Managing Partner, following his successful tenure at ADQ.\u003c/p\u003e\\n\u003cp\u003eOver the past seven years, he led the establishment and rapid transformation of ADQ into one of the world\u0026rsquo;s largest sovereign investment platforms, overseeing the growth and tripling of total assets to over USD 263 billion.\u0026nbsp;\u003c/p\u003e\",\"09198c07-d1e8-4a18-a4bb-f44f8b1746b3\",\"https://www.linkedin.com/posts/ihc-uae_ihc-wef2026-semafor-activity-7423041584423849985-oNfG?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC CEO Syed Basar Shueb spoke with Andrew Edgecliffe-Johnson from SEMAFOR during the Annual Meeting of the World Economic Forum in Davos, outlining IHC\u0026rsquo;s long-term growth ambitions and its vision to redefine the traditional holding company model.\u003cbr\u003e\u0026nbsp;\u003cbr\u003eThe interview explored IHC\u0026rsquo;s approach to building \u0026ldquo;dynamic value networks,\u0026rdquo; its disciplined investment strategy, and the central role of AI, partnerships, and scalable platforms in driving sustainable global growth across key sectors and markets.\u003cbr\u003e\u0026nbsp;\u003cbr\u003eRead the full interview here: https://lnkd.in/eiqqwH2X\u003c/p\u003e\",\"0ce01266-944e-484a-aff3-f8b1a95c849d\",\"https://www.linkedin.com/posts/ihc-uae_ihc-sirius-and-fab-receive-central-bank-activity-7427471532937007104-9Ru2?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC, Sirius International Holding, and First Abu Dhabi Bank (FAB) have announced that the Central Bank of The UAE has approved the UAE dirham-backed stablecoin DDSC to go live, marking a significant milestone in the UAE\u0026rsquo;s regulated digital finance landscape.\u0026nbsp;\u003c/p\u003e\\n\u003cp\u003eDesigned as a compliant digital financial instrument for institutional and government-led use cases, DDSC is positioned to support high-value applications including payments, settlement, treasury management, and trade flows.\u0026nbsp;\u003c/p\u003e\",\"c858f745-9dc5-4efd-bd8a-81f011994508\",\"https://www.linkedin.com/posts/ihc-uae_ihc-forbesmiddleeast-activity-7427689044458799106-IVtL?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eDaud Farooq, IHC\u0026rsquo;s Group General Counsel, joined industry leaders at the Forbes Middle East Top Advisors \u0026amp; Investors Summit in Abu Dhabi to discuss the critical role of governance and legal certainty in attracting long-term capital.\u003c/p\u003e\\n\u003cp\u003eDuring a fireside chat, Daud highlighted how forward-looking legal frameworks, predictability, and strong institutional enforcement are increasingly defining where global investors choose to deploy capital. As markets compete for international investment, trust, transparency, and disciplined governance are becoming essential enablers of sustainable growth.\u003c/p\u003e\",\"c263f575-b355-444c-834d-63ede817a94f\",\"https://www.linkedin.com/posts/ihc-uae_ihc-launches-judan-financial-activity-7428125361223352320-jwYJ?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC has announced the launch of Judan Financial Holding, a new AI-enabled North Star platform for global financial services with over AED 870 billion in assets under management.\u003cbr\u003e\u0026nbsp;\u003cbr\u003eJudan Financial will consolidate financial services assets from IHC, Alpha Dhabi Holding, 2PointZero Group and Sirius International Holding across banking, insurance, asset and wealth management, non-bank financial services and fintech. Subject to regulatory approvals, the platform is expected to oversee more than 20 operating companies across 13+ countries, serving over 11 million clients.\u003c/p\u003e\",\"15f0b2f7-d597-4fd2-b6d5-86fbd314ab5e\",\"https://www.linkedin.com/posts/ihc-uae_ihc-legal500-activity-7429437686693892096-7fVh?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eCongratulations to Mirza Hashim Baig, Senior Legal Counsel at IHC, on being recognized as \u0026ldquo;Rising Star In-house Counsel\u0026rdquo; at the Legal 500 Middle East \u0026amp; North Africa Awards 2026.\u003c/p\u003e\\n\u003cp\u003eThis recognition reflects Hashim\u0026rsquo;s dedication to navigating complex legal matters, strengthening governance frameworks, and supporting IHC\u0026rsquo;s strategic growth across the region and internationally.\u003c/p\u003e\\n\u003cp\u003eA testament to the strength of our legal function and the leadership of our Group General Counsel, Daud Farooq, this achievement highlights the depth of talent driving IHC forward.\u003c/p\u003e\",\"89f872cd-de3b-46c6-8ad4-63adcc104cdd\",\"https://www.linkedin.com/posts/ihc-uae_ihc-financialresults-dynamicvaluenetworks-activity-7431994926327943168-pVFt?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eOur full-year 2025 results reflect sustained global scale and disciplined execution across the IHC Group, driven by strong operating performance, capital recycling, and strategic portfolio expansion.\u003c/p\u003e\\n\u003cp\u003eIHC\u0026rsquo;s results were powered by landmark global transactions and platform consolidation, from the merger of 2PointZero, Multiply Group, and Ghitha Holding into a next-generation investment powerhouse, to International Resources Holding\u0026rsquo;s acquisition of Alphamin Resources Corp (AFMJF), the launch of the AI-native reinsurance platform RIQ, and the strategic partnership with Global Citizen, alongside the divestment of our stake in Modon Holding, the largest private sector transaction in UAE market history.\u003c/p\u003e\",\"51909cbb-ba6e-4059-9384-4e56f05dab30\",\"https://www.linkedin.com/posts/ihc-uae_ihc-q1-2026-activity-7458197868609171456-pfYW?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC\u0026rsquo;s Q1 2026 results reflect continued growth momentum across the IHC Group, driven by strong operating performance, disciplined capital allocation, and sustained expansion across global markets.\u003c/p\u003e\\n\u003cp\u003eRevenue increased 33.2% year-on-year to AED 31.4 billion, while Profit After Tax nearly doubled to AED 8.2 billion, supported by broad-based contributions across Real Estate \u0026amp; Construction, Marine \u0026amp; Dredging, Energy \u0026amp; Mining, Financial Services, Technology, and Hospitality \u0026amp; Leisure.\u003c/p\u003e\",\"c3a5b313-54b4-4b9a-b3c0-e32f91046283\",\"https://www.linkedin.com/posts/ihc-uae_ihc-adgm-milkeninstitute-activity-7458934452627386368-wIcx?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eA memorable evening on the sidelines of the 2026 Milken Institute Global Conference.\u003c/p\u003e\\n\u003cp\u003eIn partnership with ADGM, IHC was proud to host a private reception in Los Angeles, bringing together a select group of global leaders, investors, and policymakers for meaningful dialogue and connection.\u003c/p\u003e\",\"3a1b38c1-4ba5-4911-865e-1d87f41b0122\",\"https://www.linkedin.com/posts/ihc-uae_ihcpavilion-miite2026-makeitintheemirates-activity-7461158542461431808-Qgc6?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eFrom transformative industrial partnerships to breakthrough innovation showcases, Habiba Basiony recaps the defining moments from the IHC Pavilion at Make it in the Emirates 2026.\u003c/p\u003e\\n\u003cp\u003eOver four impactful days, IHC and its Group companies welcomed close to 100,000 visitors, hosted more than 40 sessions featuring over 70 expert speakers, and delivered over 60 strategic agreements and partnerships valued at more than AED 40 billion. The Pavilion brought together industry leaders, policymakers, and global partners to accelerate the UAE\u0026rsquo;s industrial future.\u0026nbsp;\u003c/p\u003e\",\"dfaee717-c987-4203-897e-e0c558d237fe\",\"https://www.linkedin.com/posts/ihc-uae_ihc-globalcitizennow-globalcitizen-activity-7462246044781830144-VNSE?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eBuilding on the partnership IHC announced with Global Citizen at the World Economic Forum Annual Meeting earlier this year, we were proud to participate at Global Citizen NOW in New York City last week.\u003c/p\u003e\\n\u003cp\u003eDuring the forum, H.E. Mariam bint Mohammed Almheiri, Vice Chair \u0026amp; Managing Director of 2PointZero and a member of Global Citizen's Board of Directors, joined global leaders across business, government, philanthropy, and culture to discuss turning influence into real investments for global progress.\u003c/p\u003e\",\"fb727516-73c5-4d16-9295-6847d24e81a1\",\"https://www.linkedin.com/posts/ihc-uae_ihc-financialresults-dynamicvaluenetworks-activity-7462901258044182529-UWhh?utm_source=social_share_send\u0026utm_medium=member_desktop_web\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eOur Q1 2026 results reflect continued momentum across the IHC Group, driven by strong operating performance, disciplined capital allocation, and broad-based growth across our diversified portfolio. Revenue reached AED 31.4 billion, while net profit nearly doubled to AED 8.2 billion, reinforcing the strength and resilience of our investment model.\u003c/p\u003e\",\"6396e0ce-131a-4105-af0d-de3d5837d52f\",\"https://www.linkedin.com/posts/ihc-uae_ihc-growthleaders-dynamicvaluenetworks-activity-7467686478589071360-Evwl?utm_source=share\u0026utm_medium=member_desktop\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eProud to share that IHC has been ranked #6 on TIME\u0026rsquo;s \u0026ldquo;World\u0026rsquo;s Growth Leaders of 2026\u0026rdquo; list, placing us among the top-performing publicly listed companies globally.\u003c/p\u003e\\n\u003cp\u003eThe ranking evaluates 1,000 companies worldwide based on revenue growth, financial strength, and stock performance, recognizing organizations that have demonstrated sustained growth and long-term value creation.\u003c/p\u003e\\n\u003cp\u003eWe\u0026rsquo;re also proud to see several of our group companies recognized among the world\u0026rsquo;s leading growth companies: Emirates Stallions Group ranked #35, 2PointZero Group #36, NMDC Group #71, APEX Investment P.S.C #98, Response Plus Holding PJSC #254, Alpha Dhabi Holding #329, Easy Lease Motorcycle Rental PSC #387, Ghitha Holding #429, and Invictus Investment Company PLC #860.\u003c/p\u003e\",\"b6f2dbcf-20ad-4f59-a867-ba09a02d0642\",\"https://www.linkedin.com/posts/ihc-uae_ihc-uaepledge-activity-7468274195290918914-blOe?utm_source=share\u0026utm_medium=member_desktop\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eOn behalf of IHC, our leadership, employees, and all IHC Group subsidiaries, we proudly pledge our loyalty and unwavering support to His Highness Sheikh Mohamed bin Zayed Al Nahyan, President of the UAE, may God protect him.\u003c/p\u003e\\n\u003cp\u003eUnder His Highness's leadership, the UAE has become a global benchmark for stability, resilience, and ambition.\u003c/p\u003e\\n\u003cp\u003eWe join the Pledge and Commitment initiative in gratitude for the security and prosperity we share, and in recognition of a leader who embodies the honour of this country.\u003c/p\u003e\\n\u003cp\u003eTogether, we remain committed to the UAE\u0026rsquo;s unity, stability, progress, and prosperity.\u003c/p\u003e\",\"e8c4ad02-07bd-432f-829b-e6d428db25fc\",\"https://www.linkedin.com/posts/ihc-uae_ihc-indiauae-activity-7468623653136396288-uSqh?utm_source=share\u0026utm_medium=member_desktop\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eThe UAE and India have never been closer and IHC is proud to be part of that story.\u003c/p\u003e\\n\u003cp\u003eH.E. Mariam bint Mohammed Almheiri, Vice Chair and Managing Director of 2PointZero Group, represented IHC at the Adani Group Annual Conference in Mumbai, sharing her perspective on one of the world's most dynamic and consequential economic partnerships.\u003c/p\u003e\\n\u003cp\u003eSpeaking on the panel, The India Bet: How Long-Term Capital Will Shape the USD 10 Trillion Blueprint, H.E. highlighted the role of patient capital, strategic investment, and trusted partnerships in supporting India's next phase of growth.\u003c/p\u003e\",\"ea9e020b-8ca5-4024-bc47-8dbae6c82a70\",\"https://www.linkedin.com/posts/ihc-uae_ihc-commences-aed-18-billion-initial-purchase-activity-7471231391100293139-gihw?utm_source=share\u0026utm_medium=member_desktop\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eIHC has launched the first tranche of its second share buyback programme, allocating AED 1.8 billion for the repurchase of its shares.\u003c/p\u003e\\n\u003cp\u003eThe tranche represents 36% of the approved AED 5 billion programme and reflects IHC\u0026rsquo;s strong financial position and confidence in its long-term growth trajectory. The announcement follows one of the strongest quarters in IHC\u0026rsquo;s history, with revenue reaching AED 31.4 billion and profit after tax increasing 98.5% year-on-year to AED 8.2 billion.\u003c/p\u003e\\n\u003cp\u003ePurchases will commence on 12 June 2026 in accordance with ADX regulations, with ongoing disclosures provided through ADX and IHC\u0026rsquo;s website.\u003c/p\u003e\",\"82426605-b77c-4d9a-8c44-f3d318f7bc08\",\"https://www.linkedin.com/posts/ihc-uae_ihc-ifrs18-dynamicvaluenetworks-activity-7473067123032920064-9yRQ?utm_source=share\u0026utm_medium=member_desktop\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eThe IHC Group came together today for a dedicated IFRS 18 workshop, bringing CFOs, Finance leaders, and teams from across our portfolio into one room.\u003cbr\u003e\u0026nbsp;\u003cbr\u003eDelivered in collaboration with Grant Thornton - UAE, the session focused on the upcoming IFRS 18 requirements and their implications for financial reporting, performance presentation, systems, processes, and governance across a large and diverse group.\u003cbr\u003e\u0026nbsp;\u003cbr\u003eToday\u0026rsquo;s workshop provided a valuable platform to build a shared understanding of the changes, discuss implementation considerations, and strengthen readiness throughout the Group. Beyond the technical discussions, the workshop reflected the strength of IHC\u0026rsquo;s finance cohesion, with colleagues aligning on a shared approach to reporting excellence.\u003c/p\u003e\",\"f5c7d3a2-bdda-448c-b3a5-1d8555b649ed\",\"https://www.linkedin.com/posts/ihc-uae_ihc-dynamicvaluenetworks-activity-7473768288624439296-XZee?utm_source=share\u0026utm_medium=member_desktop\u0026rcm=ACoAAAJXMKkB-2IXzLIfgK_VLbk3iysAi_-ZJi0\",\"\u003cp\u003eYesterday, IHC hosted its Group CEO Dinner, bringing together leaders from across our portfolio companies for discussions on collaboration, innovation, and the growing impact of AI across industries.\u003c/p\u003e\\n\u003cp\u003eIHC CEO Syed Basar Shueb shared perspectives on leveraging AI as a strategic tool while reinforcing the importance of collaboration in navigating an increasingly dynamic business landscape.\u003c/p\u003e\\n\u003cp\u003eThe evening offered an opportunity to exchange insights, strengthen connections across the IHC ecosystem, and explore how technology and collaboration can support long term growth and value creation.\u003c/p\u003e\",{\"_55\":837},{\"_838\":839},\"prNews\",[840,841,842,843,844,845,846,847,848,849],{\"_66\":896,\"_68\":897},{\"_66\":891,\"_68\":892},{\"_66\":886,\"_68\":887},{\"_66\":881,\"_68\":882},{\"_66\":876,\"_68\":877},{\"_66\":871,\"_68\":872},{\"_66\":866,\"_68\":867},{\"_66\":861,\"_68\":862},{\"_66\":856,\"_68\":857},{\"_66\":850,\"_68\":851},\"ihc-repositions-capital-for-global-scale-generating-aed-1114-billion-revenue-and-aed-347-billion-net-profit-in-fy-2025\",[852],{\"_17\":853,\"_854\":855},\"IHC Repositions Capital for Global Scale, Generating  AED 111.4 Billion Revenue and AED 34.7 Billion Net Profit  In FY 2025\",\"image_listing\",\"f65d5749-25f4-4cfd-b8ef-16ae35fd051c\",\"judan-financial-an-ihc-subsidiary-debuts-with-strategic-investment-in-alpha-wave-global\",[858],{\"_17\":859,\"_854\":860},\"Judan Financial, an IHC subsidiary, Debuts with Strategic Investment in Alpha Wave Global\",\"b397e79a-52f3-437b-b29d-449e0c71b721\",\"ihc-advances-usd-1-billion-investment-to-acquire-majority-stake-in-indias-sammaan-capital\",[863],{\"_17\":864,\"_854\":865},\"IHC Advances USD 1 Billion Investment to Acquire Majority Stake in India’s Sammaan Capital\",\"b1fcb1fe-d617-4c7c-ab24-3f7d4b41af16\",\"ihc-sustains-growth-momentum-in-q1-2026-with-aed-314-billion-revenue-and-net-profit-nearly-doubling-to-aed-82-billion\",[868],{\"_17\":869,\"_854\":870},\"IHC Sustains Growth Momentum in Q1 2026  with AED 31.4 Billion Revenue and  Net Profit Nearly Doubling to AED 8.2 Billion\",\"9d642db1-0bf8-4f80-95f4-35af9644b9ea\",\"ihc-reinforces-industrial-leadership-at-make-it-in-the-emirates-2026-with-aed-40-billion-in-strategic-agreements\",[873],{\"_17\":874,\"_854\":875},\"IHC Reinforces Industrial Leadership at “Make it in the Emirates 2026” with AED 40 Billion in Strategic Agreements\",\"9f83ec00-ba5a-4732-8dba-2706b7f261ba\",\"ihc-executes-landmark-aed-110-million-ddsc-transaction-on-adi-chain-advancing-institutional-adoption-of-uae-digital-infrastructure\",[878],{\"_17\":879,\"_854\":880},\"IHC Executes Landmark AED 110 Million DDSC Transaction on ADI Chain, Advancing Institutional Adoption of UAE Digital Infrastructure\",\"da01c133-ef68-49e9-88b9-76165f7a6f26\",\"ihc-commences-aed-18-billion-initial-purchase-under-approved-aed-5-billion-share-buyback-programme\",[883],{\"_17\":884,\"_854\":885},\"IHC Commences AED 1.8 Billion Initial Purchase Under Approved AED 5 Billion Share Buyback Programme\",\"39e16323-f3c0-4df8-9b06-9025b84a4621\",\"ihc-reinforces-growth-momentum-through-strategic-investments-global-expansion-and-portfolio-execution-ahead-of-h1-2026-results\",[888],{\"_17\":889,\"_854\":890},\"IHC Reinforces Growth Momentum Through Strategic Investments, Global Expansion and Portfolio Execution Ahead of H1 2026 Results\",\"c4e4d1ab-809a-426f-a316-72204e3c49e0\",\"adani-enterprises-and-ihc-group-company-irh-to-form-a-5050-joint-venture-for-usd-115-billion-aluminium-project-positioning-odisha-in-the-global-aluminium-supply-chain\",[893],{\"_17\":894,\"_854\":895},\"Adani Enterprises and IHC Group Company IRH to form a 50:50 Joint Venture for USD 11.5 Billion Aluminium Project, Positioning Odisha in the Global Aluminium Supply Chain\",\"79a55e3e-331f-4cc7-8721-4b1dc85808b0\",\"ddsc-receives-central-bank-approval-to-partner-with-selected-vara-regulated-exchange-platforms\",[898],{\"_17\":899,\"_854\":900},\"DDSC Receives Central Bank Approval to Partner with Selected VARA-Regulated Exchange Platforms\",\"0977ba29-c2f7-44ca-b8c3-17be41baf363\",{\"_55\":902},{\"_903\":904},\"portfolio\",[905,906,907,908,909,910,911,912,913,914,915,916,917],{\"_66\":989,\"_68\":990},{\"_66\":983,\"_68\":984},{\"_66\":977,\"_68\":978},{\"_66\":971,\"_68\":972},{\"_66\":965,\"_68\":966},{\"_66\":959,\"_68\":960},{\"_66\":953,\"_68\":954},{\"_66\":947,\"_68\":948},{\"_66\":761,\"_68\":942},{\"_66\":936,\"_68\":937},{\"_66\":930,\"_68\":931},{\"_66\":924,\"_68\":925},{\"_66\":918,\"_68\":919},\"technology\",[920],{\"_17\":921,\"_19\":922,\"_854\":923},\"Technology\",\"Our Technology businesses provide services that are at the forefront of the latest automation, IT services, digital technologies and industry trends. From powering secure data centers to providing AI innovation and crypto mining, we’re reshaping the future for businesses and communities.\",\"81c8a00d-da1d-4b7b-9da3-6a875d9df7aa\",\"sustainability-environment\",[926],{\"_17\":927,\"_19\":928,\"_854\":929},\"Sustainability \u0026 Environment\",\"Our Sustainability \u0026 Environment businesses are creating a greener future through innovative practices, impact investing, and climate finance. We focus on protecting natural resources, reducing environmental impact, and promoting a balance between progress and preservation.\",\"4c7a432f-ac71-4db0-b411-2aa63be8bc86\",\"real-estate-and-construction\",[932],{\"_17\":933,\"_19\":934,\"_854\":935},\"Real Estate \u0026 Construction\",\"Our Real Estate \u0026 Construction businesses deliver comprehensive solutions, including property development, commercial and contracting services, workforce management, and innovative landscaping design.\",\"3886b743-b845-4857-847f-6a1b24b73293\",\"mobility-and-logistics\",[938],{\"_17\":939,\"_19\":940,\"_854\":941},\"Mobility \u0026 Logistics\",\"Our Mobility \u0026 Logistics businesses redefine efficiency with last-mile delivery, EV infrastructure, and seamless air and freight cargo services. From motorbike rentals and concierge to comprehensive logistics solutions, we ensure holistic mobility solutions.\",\"a0169a26-5420-4ee2-aa40-0de9c5c947e8\",[943],{\"_17\":944,\"_19\":945,\"_854\":946},\"Media\",\"Our Media businesses pioneer digital out-of-home advertising, particularly in the UAE, while offering comprehensive agency services. We’re at the forefront of innovative advertising solutions, helping brands connect with their audiences in impactful ways.\",\"e8fa95c0-349b-44ea-8777-dc8b1cacfbf4\",\"marine-dredging\",[949],{\"_17\":950,\"_19\":951,\"_854\":952},\"Marine \u0026 Dredging\",\"Our Marine \u0026 Dredging businesses encompass industry-leading companies with a strong presence in the yacht and maritime sectors. We specialize in ship engineering and commercial management, driving excellence across the maritime landscape.\",\"1091565d-ffd5-4497-9e3e-3708f668698e\",\"investments\",[955],{\"_17\":956,\"_19\":957,\"_854\":958},\"Investments\",\"Our Investments portfolio drives growth by diversifying across globally and locally listed securities. By diversifying across a broad range of markets and asset classes, we mitigate risk and unlock strategic opportunities that transcend geographic boundaries.\",\"b83ea6a8-003b-49df-a167-4f3c7c1e6dab\",\"hospitality-leisure\",[961],{\"_17\":962,\"_19\":963,\"_854\":964},\"Hospitality \u0026 Leisure\",\"Our Hospitality \u0026 Leisure businesses offer unparalleled experiences through luxury hotels, fine dining, and world-class event infrastructure and management. We excel in creating unforgettable moments, delivering top-tier hospitality and leisure services around the world.\",\"8c79b4d0-e2d1-4c3c-a4d8-f2f01ef85157\",\"healthcare-wellness\",[967],{\"_17\":968,\"_19\":969,\"_854\":970},\"Healthcare \u0026 Wellness\",\"Our Healthcare \u0026 Wellness businesses span 3 continents with a vast network of private hospitals, laboratories and research centres. With the largest network of internationally accredited laboratories in the Middle East region, we’re redefining healthcare standards and delivering comprehensive medical services globally.\",\"b8cb2b10-43bd-4a23-8fdf-5e020ef3b8b5\",\"financial-services-asset-management\",[973],{\"_17\":974,\"_19\":975,\"_854\":976},\"Financial Services \u0026 Asset Management\",\"Our Financial Services \u0026 Asset Management businesses lead the way with experienced large fund management, cutting-edge digital banking, expert stock brokerage, and impactful microfinancing.\",\"cddec4ca-c5d3-41e2-bbdb-9b216a6805a6\",\"energy-utilities-and-resources\",[979],{\"_17\":980,\"_19\":981,\"_854\":982},\"Energy, Utilities \u0026 Resources\",\"Our Energy, Utilities and Resources businesses lead in sustainability, powering the future with renewable infrastructure on an industrial scale, innovative district cooling, and transformational smart meters.\",\"3e5f5c6b-0c1b-464d-ab86-a680114ec34b\",\"education\",[985],{\"_17\":986,\"_19\":987,\"_854\":988},\"Education\",\"Our Education businesses are dedicated to shaping the future, providing top-tier schooling in Abu Dhabi. We focus on delivering exceptional learning experiences that inspire and empower the next generation.\",\"3748ffca-dc4a-4f40-b1fd-cecd7a700b00\",\"food-and-agriculture\",[991],{\"_17\":992,\"_19\":993,\"_854\":994},\"Food \u0026 Agriculture\",\"Our Agriculture \u0026 Food businesses drive innovation and sustainability across the food value chain, from trading and sourcing to delivering solutions that support livestock, dairy, meat, and poultry production on a global scale.\",\"1adba992-769c-4825-b331-8f32138fed25\",{\"_55\":996},{\"_58\":997,\"_60\":998},[1011],[999,1000,1001,1002],{\"_66\":92,\"_68\":1009},{\"_66\":85,\"_68\":1007},{\"_66\":78,\"_68\":1005},{\"_66\":67,\"_68\":1003},[1004],{\"_71\":72,\"_73\":74,\"_19\":75,\"_76\":77},[1006],{\"_71\":81,\"_73\":82,\"_19\":83,\"_76\":84},[1008],{\"_71\":88,\"_73\":89,\"_19\":90,\"_76\":91},[1010],{\"_71\":95,\"_73\":96,\"_19\":97,\"_76\":98},{\"_66\":100,\"_68\":1012},[1013],{\"_71\":103,\"_73\":104,\"_19\":105,\"_76\":106},{\"_4\":1015},[1016],{\"_1017\":1018,\"_1019\":1020},\"message\",\"An unexpected error occurred.\",\"extensions\",{\"_1021\":1022},\"code\",\"INTERNAL_SERVER_ERROR\",{\"_55\":1024},{\"_1025\":1026},\"Portfolio\",[1027,1028,1029,1030,1031,1032,1033,1034,1035,1036,1037,1038,1039,1040],{\"_66\":1067,\"_68\":1068},{\"_66\":989,\"_68\":1065},{\"_66\":983,\"_68\":1063},{\"_66\":977,\"_68\":1061},{\"_66\":971,\"_68\":1059},{\"_66\":965,\"_68\":1057},{\"_66\":959,\"_68\":1055},{\"_66\":953,\"_68\":1053},{\"_66\":947,\"_68\":1051},{\"_66\":761,\"_68\":1049},{\"_66\":936,\"_68\":1047},{\"_66\":930,\"_68\":1045},{\"_66\":924,\"_68\":1043},{\"_66\":918,\"_68\":1041},[1042],{\"_17\":921,\"_854\":923,\"_19\":922},[1044],{\"_17\":927,\"_854\":929,\"_19\":928},[1046],{\"_17\":933,\"_854\":935,\"_19\":934},[1048],{\"_17\":939,\"_854\":941,\"_19\":940},[1050],{\"_1